style.css:
@-moz-document domain("schoology.com") {
/* 1. The Pompompurin Color Palette */
    body, #site-wrapper, #main {
        background-color: #fff9e6 !important; /* Soft Cream */
        color: #5d4037 !important; /* Pudding Brown */
    }

    /* 2. Top Navigation Bar (Deep Pudding Brown) */
    header, ._2u3_u, ._1Z9_S {
        background-color: #795548 !important; 
        border-bottom: 4px solid #fbc02d !important;
    }

    /* 3. The "Yellow Dog" Cards */
    .s-edge-feed, .course-item, .card, .s-card, ._1Z9_S {
        background-color: #ffffff !important;
        border: 2px solid #fdd835 !important;
        border-radius: 20px !important; /* Extra round like Pompompurin */
        box-shadow: 4px 4px 0px #ffe082 !important;
    }

    /* 4. Links and Buttons (Golden Yellow) */
    a, .s-extlink {
        color: #f57f17 !important;
        font-weight: bold !important;
    }

    .ui-button, .btn-primary {
        background-color: #fbc02d !important;
        color: #5d4037 !important;
        border-radius: 15px !important;
        border: none !important;
    }

    /* 5. Custom Background Image/GIF */
    /* This adds your GIF to the bottom right of the screen */
    body::after {
        content: "";
        background-image: url("https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHJidW5hOHR6bm9oZzR0ZzR0ZzR0ZzR0ZzR0ZzR0ZzR0ZzR0Jm0&ep=v1_internal_gif_by_id/l0HlU9p8nK1n8qF04/giphy.gif") !important;
        background-size: contain;
        background-repeat: no-repeat;
        position: fixed;
        bottom: 10px;
        right: 10px;
        width: 150px;
        height: 150px;
        z-index: 9999;
        pointer-events: none; /* Keeps it from blocking clicks */
        opacity: 0.8;
    }

    /* 6. Text Input Areas */
    input, textarea {
        background-color: #fffde7 !important;
        border: 2px solid #d7ccc8 !important;
        border-radius: 10px !important;
    }
}
